from taf.gnb.oam.megazone_client import megazone_client
from taf.gnb.oam.megazone_client.exceptions import AlarmPresentException


try:
    import unittest2 as unittest
except ImportError:
    import unittest

try:
    from mock import Mock, patch
except ImportError:
    from unittest.mock import Mock, patch


get_historic_faults_number_path = "taf.gnb.oam.megazone_client.alarms_endpoint.AlarmsEndpoint.get_historic_faults_number"
get_historic_faults_path = "taf.gnb.oam.megazone_client.alarms_endpoint.AlarmsEndpoint.get_historic_faults"


class TestBTSWithHistoricFaults(unittest.TestCase):
    def setUp(self):
        self.cor = megazone_client()
        self.cor.session_handler = Mock()
        self.cor.session_store.add(Mock())

    @patch(get_historic_faults_path, return_value=[{}, {}, {}])
    def test_get_historic_faults_number(self, m_historic):
        self.assertEqual(3, self.cor.get_historic_faults_number())

    @patch(get_historic_faults_number_path, return_value=7)
    def test_check_historic_faults_shouldFail(self, m_historic):
        with self.assertRaises(AlarmPresentException):
            self.cor.check_historic_faults()

    @patch(get_historic_faults_number_path, return_value=7)
    def test_check_active_faults_CheckSwitch_shouldPass(self, m_historic):
        self.cor.check_historic_faults(allow_negative_result=True)
